import json, os, time
from collections import defaultdict

cutoff = time.time() - 28800
hist_dir = ".state/sessions/history/"

# Track repeated reads per session
worst_sessions = []

for d in os.listdir(hist_dir):
    meta_path = os.path.join(hist_dir, d, "meta.json")
    jsonl_path = os.path.join(hist_dir, d, "session.jsonl")
    if not os.path.exists(meta_path) or not os.path.exists(jsonl_path):
        continue
    with open(meta_path) as f:
        m = json.load(f)
    ts = m.get("startedAt", 0) / 1000
    if ts <= cutoff:
        continue
    agent = m.get("agent", "?")

    # Count reads per file path
    reads = defaultdict(int)
    with open(jsonl_path) as f:
        for line in f:
            try:
                entry = json.loads(line)
                if entry.get("role") == "assistant":
                    for block in entry.get("content", []):
                        if block.get("type") == "toolCall":
                            name = block.get("name", "")
                            args = block.get("arguments", {})
                            if name == "read":
                                path = args.get("path", "")
                                reads[path] += 1
                            elif name == "bash":
                                cmd = args.get("command", "").strip()
                                if cmd.startswith("cat ") and "|" not in cmd and ">" not in cmd:
                                    # Extract path
                                    path = cmd[4:].strip().split()[0] if cmd[4:].strip() else ""
                                    if path:
                                        reads[path] += 1
            except:
                pass

    # Find duplicates
    dupes = {p: c for p, c in reads.items() if c > 1}
    if dupes:
        total_dupes = sum(c - 1 for c in dupes.values())
        worst_sessions.append((agent, d, total_dupes, dupes))

# Sort by total duplicates
worst_sessions.sort(key=lambda x: x[2], reverse=True)

print("=== Sessions with Repeated File Reads (last 8h) ===")
for agent, sid, total, dupes in worst_sessions[:15]:
    print(f"\n{agent} - {sid} ({total} redundant reads)")
    for path, count in sorted(dupes.items(), key=lambda x: x[1], reverse=True)[:5]:
        print(f"  {count}x {path}")

# Summary: total redundant reads by agent
print("\n=== Redundant Reads by Agent ===")
by_agent = defaultdict(int)
for agent, _, total, _ in worst_sessions:
    by_agent[agent] += total
for agent in sorted(by_agent, key=lambda a: by_agent[a], reverse=True):
    print(f"  {agent:12s}: {by_agent[agent]} redundant reads")
