import json, os, time
from collections import defaultdict

cutoff = time.time() - 28800
hist_dir = ".state/sessions/history/"

# Bob session analysis
print("=== Bob Sessions (last 8h) ===")
for d in sorted(os.listdir(hist_dir), key=lambda x: os.path.getmtime(os.path.join(hist_dir, x)), reverse=True):
    meta_path = os.path.join(hist_dir, d, "meta.json")
    jsonl_path = os.path.join(hist_dir, d, "session.jsonl")
    if not os.path.exists(meta_path):
        continue
    with open(meta_path) as f:
        m = json.load(f)
    ts = m.get("startedAt", 0) / 1000
    if ts <= cutoff or m.get("agent") != "bob":
        continue
    sz = os.path.getsize(jsonl_path) if os.path.exists(jsonl_path) else 0
    ops = m.get("opCount", 0)

    # Count reads/writes and large tool results
    reads = []
    large_results = 0
    total_result_bytes = 0
    with open(jsonl_path) as f:
        for line in f:
            try:
                entry = json.loads(line)
                if entry.get("role") == "assistant":
                    for block in entry.get("content", []):
                        if block.get("type") == "toolCall" and block.get("name") == "read":
                            reads.append(block.get("arguments",{}).get("path",""))
                if entry.get("role") == "tool":
                    for block in entry.get("content", []):
                        result_text = block.get("text", "") if isinstance(block, dict) else str(block)
                        result_len = len(result_text)
                        total_result_bytes += result_len
                        if result_len > 5000:
                            large_results += 1
            except:
                pass

    print(f"\n  {d}: {sz/1024:.0f}KB, {ops} ops, {len(reads)} reads, {large_results} large results ({total_result_bytes/1024:.0f}KB results)")
    if reads:
        for r in reads[:8]:
            print(f"    read: {r}")

# Also check: what files does Bob read most across sessions?
print("\n=== Bob's Most-Read Files ===")
file_reads = defaultdict(int)
for d in os.listdir(hist_dir):
    meta_path = os.path.join(hist_dir, d, "meta.json")
    jsonl_path = os.path.join(hist_dir, d, "session.jsonl")
    if not os.path.exists(meta_path) or not os.path.exists(jsonl_path):
        continue
    with open(meta_path) as f:
        m = json.load(f)
    ts = m.get("startedAt", 0) / 1000
    if ts <= cutoff or m.get("agent") != "bob":
        continue
    with open(jsonl_path) as f:
        for line in f:
            try:
                entry = json.loads(line)
                if entry.get("role") == "assistant":
                    for block in entry.get("content", []):
                        if block.get("type") == "toolCall" and block.get("name") == "read":
                            file_reads[block.get("arguments",{}).get("path","")] += 1
            except:
                pass

for path in sorted(file_reads, key=lambda p: file_reads[p], reverse=True)[:10]:
    print(f"  {file_reads[path]}x {path}")
